#!/usr/bin/env node
// cargo-dist 0.32.0 permits skipped builds in host's always() condition, even
// when a custom plan prerequisite failed. Keep only that prerequisite stricter
// than upstream, and compare ALL generated bytes rather than waive freshness.
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const assert = require('node:assert/strict');
const { execFileSync } = require('node:child_process');
const root = path.resolve(__dirname, '../..');
const workflow = '.github/workflows/release.yml';
const files = ['dist-workspace.toml', 'README.md', 'LICENSE-MIT', 'LICENSE-APACHE',
  'kio-rs/Cargo.toml', 'kio-rs/Cargo.lock', 'kio-rs/build.rs', 'kio-rs/README.md',
  'kio-rs/LICENSE-MIT', 'kio-rs/LICENSE-APACHE', 'kio-rs/dist/Cargo.toml',
  'kio-rs/dist/Cargo.lock', 'kio-rs/dist/build.rs', 'kio-rs/src/lib.rs',
  'kio-rs/src/main.rs', 'kio-rs/src/bin/kio-prime.rs'];
function augment(raw) {
  assert(raw.includes('  custom-release-credentials:\n    uses: ./.github/workflows/release-credentials.yml\n'), 'missing credential plan hook');
  const build = raw.match(/^  build-local-artifacts:\n([\s\S]*?)(?=^  [\w-]+:)/m)?.[1];
  assert(build && /    needs:\n(?:      - [\w-]+\n)*      - custom-release-credentials\n/.test(build), 'missing build prerequisite');
  const anchor = '  host:\n    needs:\n';
  assert.equal(raw.split(anchor).length, 2, 'upstream host structure changed');
  const condition = "    if: ${{ always() && needs.plan.result == 'success'";
  assert.equal(raw.split(condition).length, 2, 'upstream host condition changed');
  assert(!raw.includes("needs.custom-release-credentials.result"), 'already augmented');
  const localCondition = '    if: ${{ fromJson(needs.plan.outputs.val).ci.github.artifacts_matrix.include';
  assert.equal(raw.split(localCondition).length, 2, 'upstream build condition changed');
  const verified = "needs.custom-release-credentials.outputs.verified == 'true' && ";
  return raw.replace(anchor, `${anchor}      - custom-release-credentials\n`)
    .replace(condition, "    if: ${{ always() && needs.custom-release-credentials.result == 'success' && " + verified + "needs.plan.result == 'success'")
    .replace(localCondition, '    if: ${{ ' + verified + 'fromJson(needs.plan.outputs.val).ci.github.artifacts_matrix.include');
}
function assertFresh(expected, actual) {
  assert.equal(actual, expected, 'release.yml is stale; run node ci/infra/release-workflow.cjs --generate');
}
function inputs(read, exists, list) {
  const config = read('dist-workspace.toml');
  assert(/^members = \["cargo:kio-rs\/dist"\]$/m.test(config), 'unsupported dist workspace');
  assert.equal((config.match(/^members\s*=/gm) || []).length, 1);
  // New generator options can introduce file inputs (including build setup or
  // release submodules); extend this bounded model deliberately, not silently.
  const keys = new Set(['members', 'cargo-dist-version', 'allow-dirty', 'ci', 'installers',
    'targets', 'hosting', 'github-release', 'plan-jobs', 'publish-jobs', 'github-custom-job-permissions']);
  for (const match of config.matchAll(/^\s*([\w-]+)\s*=/gm))
    assert(keys.has(match[1]), `unsupported dist input: ${match[1]}`);
  assert(!exists('dist.toml') && !exists('kio-rs/dist/dist.toml'), 'unmodeled dist config');
  const expectedPaths = [['kio-rs/Cargo.toml', ['src/lib.rs', 'src/main.rs', 'src/bin/kio-prime.rs']],
    ['kio-rs/dist/Cargo.toml', ['../src/main.rs', '..']]];
  for (const [file, expected] of expectedPaths) {
    const manifest = read(file);
    assert.deepEqual([...manifest.matchAll(/\bpath\s*=\s*"([^"]+)"/g)].map(m => m[1]), expected, `unsupported paths in ${file}`);
    assert(!/\b(workspace|license-file)\s*=|^\[workspace\]/m.test(manifest), `unsupported workspace/file input in ${file}`);
    const readmes = [...manifest.matchAll(/^readme\s*=\s*"([^"]+)"/gm)].map(m => m[1]);
    assert.deepEqual(readmes, file === 'kio-rs/Cargo.toml' ? ['README.md'] : []);
  }
  // The dist workspace's single executable is explicit. Reject new automatic
  // targets rather than silently generate from an incomplete metadata view.
  for (const dir of ['src', 'tests', 'examples', 'benches'])
    assert(!exists(`kio-rs/dist/${dir}`), `new dist targets in ${dir}`);
  assert.deepEqual(list('kio-rs/src/bin').sort(), ['kio-prime.rs'], 'new compiler binary target');
  return config;
}
function run(mode, dist = 'dist') {
  assert(['--check', '--generate'].includes(mode), 'use --check or --generate');
  const config = inputs(file => fs.readFileSync(path.join(root, file), 'utf8'),
    file => fs.existsSync(path.join(root, file)), dir => fs.readdirSync(path.join(root, dir)));
  const version = config.match(/^cargo-dist-version = "([^"]+)"$/m)?.[1];
  assert(version, 'missing cargo-dist version');
  assert.equal(execFileSync(dist, ['--version'], { encoding: 'utf8' }).trim(), `cargo-dist ${version}`, 'wrong cargo-dist version');
  const temp = fs.mkdtempSync(path.join(os.tmpdir(), 'kio-release-workflow-'));
  try {
    for (const file of files) {
      const target = path.join(temp, file);
      fs.mkdirSync(path.dirname(target), { recursive: true });
      fs.copyFileSync(path.join(root, file), target);
    }
    assert.equal((config.match(/^allow-dirty = \["ci"\]$/gm) || []).length, 1, 'expected narrow CI freshness waiver');
    fs.writeFileSync(path.join(temp, 'dist-workspace.toml'), config.replace(/^allow-dirty = \["ci"\]\n/m, ''));
    execFileSync(dist, ['generate', '--mode=ci'], { cwd: temp, timeout: 60000, stdio: 'pipe' });
    const expected = augment(fs.readFileSync(path.join(temp, workflow), 'utf8'));
    if (mode === '--check') assertFresh(expected, fs.readFileSync(path.join(root, workflow), 'utf8'));
    else fs.writeFileSync(path.join(root, workflow), expected);
    console.log(`release workflow ${mode === '--check' ? 'matches exact generated bytes plus credential prerequisite' : 'regenerated'}`);
  } finally { fs.rmSync(temp, { recursive: true, force: true }); }
}
module.exports = { augment, assertFresh, inputs };
if (require.main === module) {
  try { run(process.argv[2], process.argv[3]); }
  catch (error) { console.error(error.message); process.exitCode = 1; }
}
